export function familyOf(drug: Drug): Family {
  return families.find((f) => f.id === drug.familyId)!;
}

export function drugById(id: string): Drug | undefined {
  return drugs.find((d) => d.id === id);
}

export function drugsInFamily(familyId: string): Drug[] {
  return drugs.filter((d) => d.familyId === familyId);
}
